-- Candidatory per-user onboarding (neutral recommendations, not legal eligibility verdicts)
CREATE TABLE IF NOT EXISTS candidate_profiles(telegram_id INTEGER PRIMARY KEY REFERENCES candidate_users(telegram_id) ON DELETE CASCADE,election_type TEXT NOT NULL CHECK(election_type IN ('council','parliament','presidency','other')),district TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL CHECK(stage IN ('planning','registration','operations','report')),professional_summary TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS candidate_checklist_items(id TEXT PRIMARY KEY,telegram_id INTEGER NOT NULL REFERENCES candidate_users(telegram_id) ON DELETE CASCADE,item_key TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','done')),source_type TEXT NOT NULL DEFAULT 'recommended',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(telegram_id,item_key));
CREATE INDEX IF NOT EXISTS idx_candidate_checklist_owner ON candidate_checklist_items(telegram_id,status);
